from typing import List

def solve(times: List[str]) -> str:
    def time_to_minutes(time: str) -> int:
        return int(time[:2]) * 60 + int(time[2:])

    def minutes_to_time(minutes: int) -> str:
        hours = minutes // 60
        minutes = minutes % 60
        return f"{hours:02d}:{minutes:02d}"

    sorted_times = sorted(set(map(time_to_minutes, times)))
    max_interval = (sorted_times[0] + 1440 - sorted_times[len(sorted_times) - 1]) % 1440

    for i in range(1, len(sorted_times)):
        max_interval = max(max_interval, sorted_times[i] - sorted_times[i - 1] - 1)

    return minutes_to_time(max_interval)

# Example usage:
# print(solve(["14:51"]))  # Output: "23:59"
# print(solve(["23:00", "04:22", "18:05", "06:24"]))  # Output: "11:40"
